import { Modal } from '@/components/ui';
import { ProfileView } from '@/components/casefile/ProfileView';
import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import QRCode from 'qrcode';
import type { DocKey, Student } from '@/types';
import { evaluateEligibility, type StudentEvidence } from '@/engines/eligibility';
import type { OfflineOperation, PilotAction, PilotApplication, PilotRecord, PilotSnapshot, PilotTarget } from './types';
import * as api from './api';
import * as offline from './offline';
import { analyticsCsv, computePilotAnalytics, parseBaselineCsv } from './analytics';
import { csv, download } from './exports';
import PilotAssistant from './PilotAssistant';
import InstallPilot from './InstallPilot';
import DataPages from './DataPages';
import {PrivacyNotice,PrivacyTools} from './PrivacyTools';
import { AccountTools, OperationsTools, InstitutionTools, OfficerNoteForm, ApplicationLifecycle, AuditTools, BulkSanction, DeliveryTools, SchemeTools, ConflictReview, ErasureRequest, GrievanceCategories, GrievanceTools, SourceHealthTools } from './WorkflowTools';
import './pilot.css';
import { AuthLayout, Brand, GovernmentBanner } from '@/components/casefile/Casefile';
